import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class FastDateFormat_format_TriageGen1Test {

    @Test
    public void testFormatWithSimplePattern() {
        String pattern = "yyyy-MM-dd";
        FastDateFormat fdf = FastDateFormat.getInstance(pattern);

        // Use a fixed date: 2023-10-27 10:00:00 UTC
        Calendar cal = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
        cal.set(2023, Calendar.OCTOBER, 27, 10, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        Date date = cal.getTime();

        String result = fdf.format(date);
        assertEquals("2023-10-27", result);
    }

    @Test
    public void testFormatWithTimeZone() {
        String pattern = "HH:mm";
        TimeZone tz = TimeZone.getTimeZone("GMT+8");
        FastDateFormat fdf = FastDateFormat.getInstance(pattern, tz);

        // 2023-10-27 10:00:00 UTC -> 2023-10-27 18:00:00 GMT+8
        Calendar cal = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
        cal.set(2023, Calendar.OCTOBER, 27, 10, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        Date date = cal.getTime();

        String result = fdf.format(date);
        assertEquals("18:00", result);
    }

    @Test
    public void testFormatWithLocale() {
        String pattern = "MMMM";
        Locale locale = Locale.FRENCH;
        FastDateFormat fdf = FastDateFormat.getInstance(pattern, Locale.getDefault(), locale);

        Calendar cal = Calendar.getInstance();
        cal.set(2023, Calendar.OCTOBER, 1);
        Date date = cal.getTime();

        String result = fdf.format(date);
        // October in French is "octobre"
        assertEquals("octobre", result.toLowerCase());
    }

    @Test
    public void testFormatWithDateTimeInstance() {
        // Test the static factory method for Date/Time styles
        FastDateFormat fdf = FastDateFormat.getDateTimeInstance(Calendar.SHORT, Calendar.SHORT);
        Date date = new Date();

        String result = fdf.format(date);
        assertNotNull(result);
        // Since style depends on locale, we just check it's not null and produced a string
    }

    @Test
    public void testFormatWithLongMillis() {
        // The class provides format(long millis) which internally uses the same logic
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        long millis = 1698393600000L; // 2023-10-27

        String result = fdf.format(millis);
        assertEquals("2023", result);
    }

    @Test
    public void testFormatWithCalendar() {
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        Calendar cal = Calendar.getInstance();
        cal.set(2025, Calendar.JANUARY, 1);

        String result = fdf.format(cal);
        assertEquals("2025", result);
    }

    @Test
    public void testFormatEdgeCaseDate() {
        // Test epoch
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy-MM-dd");
        Date epoch = new Date(0);

        // Note: Result depends on default TimeZone, but pattern should hold
        String result = fdf.format(epoch);
        assertNotNull(result);
        assertEquals(10, result.length());
    }

    @Test
    public void testFormatComplexPattern() {
        String pattern = "yyyy/MM/dd HH:mm:ss.SSS";
        FastDateFormat fdf = FastDateFormat.getInstance(pattern);

        Calendar cal = Calendar.getInstance();
        cal.set(2023, Calendar.DECEMBER, 31, 23, 59, 59);
        cal.set(Calendar.MILLISECOND, 999);
        Date date = cal.getTime();

        String result = fdf.format(date);
        // We check if the result contains the expected year and month
        // Using contains because of potential timezone offsets in local test env
        assertNotNull(result);
        assertEquals(true, result.contains("2023"));
        assertEquals(true, result.contains("12"));
    }
}
